"""The agent's two tools.

There's no artificial intelligence in here: just two plain, ordinary Python
functions. The model doesn't run them, it only ASKS for them to run.
Your program is what runs them, so you decide what it can ask for and what not.
"""

import json
import sys
from pathlib import Path

CARPETA = Path(__file__).parent
BORRADORES = CARPETA / "borradores"

# Load the fake store once, at startup.
try:
    PEDIDOS = json.loads((CARPETA / "pedidos.json").read_text(encoding="utf-8"))
except FileNotFoundError:
    sys.exit("Can't find pedidos.json. It needs to be in the same folder as this file.")

# Words the agent is NOT allowed to write on its own. Promising money is a
# business decision: a person makes it, not a model that costs a fraction of a cent.
PROMESAS_PROHIBIDAS = [
    "reembolso", "reembolsar", "devolvemos el dinero", "descuento",
    "cupón", "cupon", "vale de", "indemniz", "compensación económica",
]

LIMITE_CARACTERES = 1200


def consultar_pedido(numero_pedido: str) -> dict:
    """Looks up an order in pedidos.json and returns its real data."""
    numero = str(numero_pedido or "").strip().upper()
    pedido = PEDIDOS.get(numero)
    if pedido is None:
        return {
            "error": (
                f"There is no order with the number {numero}. "
                "Do not make up data: write a reply asking the customer "
                "to confirm the number from their confirmation email."
            )
        }
    # Internal data never goes out to the customer, but the agent does
    # need it to decide what to say.
    return {"numero_pedido": numero, **pedido}


def redactar_respuesta(numero_pedido: str, asunto: str, cuerpo: str) -> dict:
    """Saves the draft reply. Sends NOTHING.

    Before saving, it runs through four checks. If any fails it returns an
    error with the explanation, and the agent will have to rewrite the text.
    """
    numero = str(numero_pedido or "").strip().upper()
    asunto = str(asunto or "").strip()
    cuerpo = str(cuerpo or "").strip()

    # Check 1: the order has to actually exist.
    if numero not in PEDIDOS:
        return {"error": f"Order {numero} does not exist. Look it up before writing the reply."}

    # Check 2: the order number has to appear in the text.
    if numero not in cuerpo:
        return {"error": f"The text doesn't mention order {numero}. Add it and call me again."}

    # Check 3: length. Not a wall of text, not two bare lines.
    if len(cuerpo) > LIMITE_CARACTERES:
        return {"error": f"The text is {len(cuerpo)} characters and the max is {LIMITE_CARACTERES}. Shorten it."}
    if len(cuerpo) < 120:
        return {"error": f"The text is {len(cuerpo)} characters. That's too curt: explain the order's status."}

    # Check 4: no promising money.
    minusculas = cuerpo.lower()
    for palabra in PROMESAS_PROHIBIDAS:
        if palabra in minusculas:
            return {
                "error": (
                    f"You wrote \u00abt{palabra}\u00bb. You cannot promise money or compensation: "
                    "a person decides that. Rewrite the text without promising anything and say "
                    "a teammate will review the case and reply within 24 business hours."
                )
            }

    BORRADORES.mkdir(exist_ok=True)
    destinatario = PEDIDOS[numero]["email"]
    ruta = BORRADORES / f"{numero}.txt"
    ruta.write_text(f"To: {destinatario}\nSubject: {asunto}\n\n{cuerpo}\n", encoding="utf-8")

    return {
        "ok": True,
        "destinatario": destinatario,
        "archivo": ruta.name,
        "aviso": "Draft saved. NOTHING has been sent. Your job is done: "
                 "reply with one sentence summarizing what you did and call no more tools.",
    }


# Each tool's spec sheet: the only thing the model ever sees of them.
# If the description is badly written, the model will misuse it. It's a prompt, not code.
FICHAS = [
    {
        "name": "consultar_pedido",
        "description": (
            "Looks up an order's real status in the store's database. "
            "Use it ALWAYS before writing anything. Don't trust what the customer "
            "says or what you think you remember."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "numero_pedido": {
                    "type": "string",
                    "description": "Order number in the format PED-1042",
                }
            },
            "required": ["numero_pedido"],
        },
    },
    {
        "name": "redactar_respuesta",
        "description": (
            "Saves the draft reply to the customer so a person can review it. "
            "Sends nothing. Call it exactly once, once you have the order's data."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "numero_pedido": {"type": "string", "description": "Order number, format PED-1042"},
                "asunto": {"type": "string", "description": "Email subject, max 60 characters"},
                "cuerpo": {"type": "string", "description": "Full email text, already written and signed"},
            },
            "required": ["numero_pedido", "asunto", "cuerpo"],
        },
    },
]

FUNCIONES = {
    "consultar_pedido": consultar_pedido,
    "redactar_respuesta": redactar_respuesta,
}


if __name__ == "__main__":
    # Quick test without spending a cent: this calls no model at all.
    print("1) An order that exists:")
    print("  ", consultar_pedido("ped-1042")["estado"], "-", consultar_pedido("PED-1042")["seguimiento"])
    print("2) A made-up order:")
    print("  ", consultar_pedido("PED-9999")["error"])
    print("3) A draft that promises a discount (must bounce):")
    print("  ", redactar_respuesta("PED-1042", "Your order", "Hi Marta, your order PED-1042 is running late. "
                                   "We're giving you a 10% discount on your next purchase to make up for it. "
                                   "We're very sorry for the inconvenience. Zapatos Mendieta Team.")["error"])
